svg.script:
(function() {
  const root = document.getElementById('a12p18-2h-root');
  if (!root) return;

  // Knowledge Base for Dynamic Panel Updating
  const kb = {
    'all': {
      badge: 'MAPA COMPLETO DO PERÍNEO',
      badgeClass: 'a12p18-2h-badge-tug',
      badgeColor: 'var(--a12p18-2h-tug-color, #ec407a)',
      title: 'VISÃO GERAL ANATÔMICA',
      subtitle: 'Divisão em 2 Trígonos e a Convergência Muscular',
      p1: '• Trígono Urogenital (Anterior): Contém 3 músculos superficiais (Isquiocavernoso, Bulboesponjoso, Transverso Superficial).',
      p2: '• Trígono Anal (Posterior): Contém 1 músculo (Esfíncter Externo do Ânus).',
      p3: '• Linha Bituberosa: Marco divisor horizontal unindo as duas tuberosidades isquiáticas.',
      clinTitle: 'REGRA DE OURO DAS PROVAS DE RESIDÊNCIA',
      clinBody: 'Guarde: 3 músculos no TUG + 1 músculo no TA = 4 convergindo no Corpo Perineal.',
      clinT1: 'Em provas, a anatomia superficial do períneo é cobrada quanto ao número de músculos por trígono e ao ponto central de fixação tendínea.',
      clinT2: 'A integridade da fáscia e músculos evita o colapso do assoalho pélvico.',
      takeaway: 'O períneo é um losango dividido pela linha bituberosa em 2 trígonos. O Corpo Perineal é a chave de abóbada onde 4 músculos se ancoram.'
    },
    'tug': {
      badge: 'TRÍGONO UROGENITAL (ANTERIOR)',
      badgeClass: 'a12p18-2h-badge-tug',
      badgeColor: 'var(--a12p18-2h-tug-color, #ec407a)',
      title: 'TRÍGONO UROGENITAL (TUG)',
      subtitle: 'Região Anterior Composta por 3 Músculos Superficiais',
      p1: '1. M. Isquiocavernoso: Recobre os ramos isquiopúbicos e crura do clitóris.',
      p2: '2. M. Bulboesponjoso: Circunda o óstio vaginal e bulbo do vestíbulo.',
      p3: '3. M. Transverso Superficial do Períneo: Fixa a margem posterior do TUG.',
      clinTitle: 'EPISIOTOMIA MEDIOLATERAL (ANATOMIA)',
      clinBody: 'Corta o M. Bulboesponjoso e o M. Transverso Superficial do Períneo.',
      clinT1: 'A incisão mediolateral incisa os músculos do TUG lateralmente para proteger o Corpo Perineal e o Esfíncter Anal de lacerações graves.',
      clinT2: 'A Membrana Perineal serve de assoalho fibroso profundo para este trígono.',
      takeaway: 'Os 3 músculos do TUG (Isquiocavernoso, Bulboesponjoso e Transverso Superficial) mantêm o suporte dos órgãos urogenitais e eréteis.'
    },
    'ta': {
      badge: 'TRÍGONO ANAL (POSTERIOR)',
      badgeClass: 'a12p18-2h-badge-ta',
      badgeColor: 'var(--a12p18-2h-ta-color, #ab47bc)',
      title: 'TRÍGONO ANAL (TA)',
      subtitle: 'Região Posterior Composta por 1 Músculo Superficial',
      p1: '• Músculo Principal: Esfíncter Externo do Ânus (EEA).',
      p2: '• Fixação Anterior: Ancorado diretamente no Corpo Perineal.',
      p3: '• Fixação Posterior: Conectado ao Cóccix pelo Ligamento Anocóccigeo.',
      clinTitle: 'LACERAÇÃO PERINEAL DE 3º E 4º GRAUS',
      clinBody: 'Laceração de 3º grau atinge o Esfíncter Anal; 4º grau atinge a mucosa retal.',
      clinT1: 'O Trígono Anal possui a Fossa Isquioanal preenchida por tecido adiposo, permitindo a expansão do canal anal durante a evacuação.',
      clinT2: 'O EEA é o único músculo superficial do Trígono Anal.',
      takeaway: 'O Trígono Anal possui apenas 1 músculo superficial (EEA), que estabelece a ponte muscular entre o Corpo Perineal e o Cóccix.'
    },
    'cp': {
      badge: 'CONVERGÊNCIA MIOFASCIAL',
      badgeClass: 'a12p18-2h-badge-tug',
      badgeColor: 'var(--a12p18-2h-cp-color, #26a69a)',
      title: 'CORPO PERINEAL (CENTRO TENDÍNEO)',
      subtitle: 'Nó Fibromuscular de Suporte do Assoalho Pélvico',
      p1: '• Convergência Anterior: M. Bulboesponjoso (puxa superiormente).',
      p2: '• Convergência Lateral: M. Transverso Superficial do Períneo (D e E).',
      p3: '• Convergência Posterior: M. Esfíncter Externo do Ânus.',
      clinTitle: 'PONTO CRÍTICO DA EPISIOTOMIA MEDIANA',
      clinBody: 'A episiotomia mediana secciona diretamente o Corpo Perineal.',
      clinT1: 'Seccionado ou lacerado criticamente, o Corpo Perineal perde a tensão vetorial, levando à incompetência perineal e prolapsos de órgão pélvicos.',
      clinT2: 'Vetores de tração opostos estabilizam o centro do períneo como uma chave de abóbada.',
      takeaway: 'O Corpo Perineal é o ponto cego da sustentação pélvica: 4 músculos convergem nele para neutralizar as forças de tração do períneo.'
    },
    'isquiocavernoso': {
      badge: 'TRÍGONO UROGENITAL (TUG)',
      badgeClass: 'a12p18-2h-badge-tug',
      badgeColor: 'var(--a12p18-2h-m-ic, #e91e63)',
      title: 'M. ISQUIOCAVERNOSO',
      subtitle: 'Músculo Par Lateral do Trígono Urogenital',
      p1: '• Origem: Face interna da Tuberosidade Isquiática e Ramo Isquiopúbico.',
      p2: '• Inserção: Aponeurose sobre o Pilar/Ramo do Clitóris (Crus clitoridis).',
      p3: '• Função: Comprime os pilares do clitóris, retardando o retorno venoso.',
      clinTitle: 'IDENTIFICAÇÃO ANATÔMICA EM PROVAS',
      clinBody: 'Acompanha a borda óssea lateral do Trígono Urogenital.',
      clinT1: 'Não se fixa no Corpo Perineal (diferente do Bulboesponjoso e Transverso Superficial). Corre estritamente ao longo do osso.',
      clinT2: 'Sua lesão em traumas ósseos pélvicos pode causar hematomas vulvares volumosos.',
      takeaway: 'O M. Isquiocavernoso abraça a borda óssea isquiopúbica lateral e atua na função erétil, sem se fixar no Corpo Perineal.'
    },
    'bulboesponjoso': {
      badge: 'TRÍGONO UROGENITAL (TUG)',
      badgeClass: 'a12p18-2h-badge-tug',
      badgeColor: 'var(--a12p18-2h-m-be, #f48fb1)',
      title: 'M. BULBOESPONJOSO',
      subtitle: 'Músculo Par Medial Encircundante do Óstio Vaginal',
      p1: '• Origem: Corpo Perineal (posteriorment).',
      p2: '• Inserção: Corpos cavernosos do clitóris e fáscia do bulbo do vestíbulo.',
      p3: '• Função: Comprime o bulbo do vestíbulo e constringe a abertura vaginal.',
      clinTitle: 'CIRURGIA OBSTÉTRICA & EPISIOTOMIA',
      clinBody: 'Principal músculo seccionado na episiotomia mediolateral.',
      clinT1: 'Sua integridade garante o tônus do introitus vaginal. Na episiorrafia, a reaproximação anatômica correta do bulboesponjoso é fundamental.',
      clinT2: 'Forma as paredes laterais do hiato urogenital superficial.',
      takeaway: 'O M. Bulboesponjoso contorna a vagina e conecta a região clitoridiana anterior diretamente ao Corpo Perineal.'
    },
    'transverso-superficial': {
      badge: 'TRÍGONO UROGENITAL (TUG)',
      badgeClass: 'a12p18-2h-badge-tug',
      badgeColor: 'var(--a12p18-2h-m-tsp, #ff80ab)',
      title: 'M. TRANSVERSO SUPERFICIAL',
      subtitle: 'Músculo Par Transversal na Base do TUG',
      p1: '• Origem: Face interna da Tuberosidade Isquiática.',
      p2: '• Inserção: Corpo Perineal (Centro Tendíneo do Períneo).',
      p3: '• Função: Estabiliza o Corpo Perineal e fixa a margem posterior da membrana.',
      clinTitle: 'RELAÇÃO COM A LINHA BITUBEROSA',
      clinBody: 'Corre exatamente paralelo à Linha Bituberosa de divisão.',
      clinT1: 'Seccionado na episiotomia mediolateral. Sua tração lateral ajuda a manter o centro do períneo alinhado no plano sagital.',
      clinT2: 'Marca o limite posterior do Trígono Urogenital.',
      takeaway: 'O M. Transverso Superficial do Períneo age como uma corda esticada entre a tuberosidade isquiática e o Corpo Perineal.'
    },
    'esfincter-anal': {
      badge: 'TRÍGONO ANAL (TA)',
      badgeClass: 'a12p18-2h-badge-ta',
      badgeColor: 'var(--a12p18-2h-m-eea, #ba68c8)',
      title: 'M. ESFÍNCTER EXTERNO DO ÂNUS',
      subtitle: 'Músculo Único do Trígono Anal Superficial',
      p1: '• Origem/Fixação Anterior: Corpo Perineal.',
      p2: '• Fixação Posterior: Cóccix (através do Ligamento Anocóccigeo).',
      p3: '• Função: Continência fecal voluntária e constrição do canal anal.',
      clinTitle: 'RISCO EM LACERAÇÕES PERINEAIS GRAVES',
      clinBody: 'Laceração de 3º Grau = Atinge fibras do Esfíncter Anal (EEA).',
      clinT1: 'Lacerações obstétricas que se estendem do introitus vaginal em linha reta mediana rompem o Corpo Perineal e atingem o EEA (3º grau).',
      clinT2: 'Único representante muscular superficial do Trígono Anal.',
      takeaway: 'O M. Esfíncter Externo do Ânus é o guardião da continência fecal e a ancoragem posterior do Corpo Perineal até o Cóccix.'
    },
    'corpo-perineal': {
      badge: 'CONVERGÊNCIA MIOFASCIAL',
      badgeClass: 'a12p18-2h-badge-tug',
      badgeColor: 'var(--a12p18-2h-cp-color, #26a69a)',
      title: 'CORPO PERINEAL (CENTRO TENDÍNEO)',
      subtitle: 'Nó Fibromuscular de Suporte do Assoalho Pélvico',
      p1: '• Convergência Anterior: M. Bulboesponjoso (puxa superiormente).',
      p2: '• Convergência Lateral: M. Transverso Superficial do Períneo (D e E).',
      p3: '• Convergência Posterior: M. Esfíncter Externo do Ânus.',
      clinTitle: 'PONTO CRÍTICO DA EPISIOTOMIA MEDIANA',
      clinBody: 'A episiotomia mediana secciona diretamente o Corpo Perineal.',
      clinT1: 'Seccionado ou lacerado criticamente, o Corpo Perineal perde a tensão vetorial, levando à incompetência perineal e prolapsos de órgão pélvicos.',
      clinT2: 'Vetores de tração opostos estabilizam o centro do períneo como uma chave de abóbada.',
      takeaway: 'O Corpo Perineal é o ponto cego da sustentação pélvica: 4 músculos convergem nele para neutralizar as forças de tração do períneo.'
    },
    'membrana-perineal': {
      badge: 'MARCO FASCIA PROFUNDO',
      badgeClass: 'a12p18-2h-badge-ta',
      badgeColor: 'var(--a12p18-2h-membrane-stroke, #7b1fa2)',
      title: 'MEMBRANA PERINEAL',
      subtitle: 'Lâmina Fibrosa Triangular do Trígono Urogenital',
      p1: '• Localização: Cobre todo o Trígono Urogenital (profunda aos músculos).',
      p2: '• Fixação: Ramos isquiopúbicos lateralmente e linha bituberosa posterior.',
      p3: '• Perfurações: Atravessada pela Uretra e pela Vagina.',
      clinTitle: 'DIVISOR ANATÔMICO DE ANDARES',
      clinBody: 'Separa o Espaço Superficial do Períneo do Espaço Profundo.',
      clinT1: 'Toda estrutura superficial à membrana pertence ao espaço superficial do períneo (incluindo os 3 músculos do TUG).',
      clinT2: 'Fornece sustentação passiva essencial para a uretra média e vagina anterior.',
      takeaway: 'A Membrana Perineal é o tablado fibroso do Trígono Urogenital que sustenta as estruturas eréteis e separa os andares perineais.'
    },
    'linha-bituberosa': {
      badge: 'EIXO DE DIVISÃO ANATÔMICA',
      badgeClass: 'a12p18-2h-badge-tug',
      badgeColor: 'var(--a12p18-2h-line-color, #ffa726)',
      title: 'LINHA BITUBEROSA',
      subtitle: 'Linha Imaginária Horizontal entre as Tuberosidades Isquiáticas',
      p1: '• Ponto Inicial/Final: Tuberosidade Isquiática Direita à Esquerda.',
      p2: '• Cruzamento: Cruza exatamente o Corpo Perineal no centro.',
      p3: '• Função Divisória: Separa o Trígono Urogenital (ant) do Trígono Anal (post).',
      clinTitle: 'MARCO ANATÔMICO DE REFERÊNCIA',
      clinBody: 'Divide o períneo em 2 triângulos topográficos distintos.',
      clinT1: 'Fundamental em exames físicos e cirurgias proctológicas e ginecológicas para delimitação de margens de segurança.',
      clinT2: 'Paralela às fibras do M. Transverso Superficial do Períneo.',
      takeaway: 'A Linha Bituberosa é a fronteira invisível que mapeia o períneo em área urogenital anterior e anal posterior.'
    }
  };

  // Function to update the readout panel
  function updatePanel(key) {
    const data = kb[key] || kb['all'];

    const badgeBg = document.getElementById('a12p18-2h-panel-badge-bg');
    const badgeText = document.getElementById('a12p18-2h-panel-badge-text');
    const title = document.getElementById('a12p18-2h-panel-title');
    const subtitle = document.getElementById('a12p18-2h-panel-subtitle');

    const p1 = document.getElementById('a12p18-2h-desc-p1');
    const p2 = document.getElementById('a12p18-2h-desc-p2');
    const p3 = document.getElementById('a12p18-2h-desc-p3');

    const clinTitle = document.getElementById('a12p18-2h-clinical-box-title');
    const clinBody = document.getElementById('a12p18-2h-clinical-box-body');
    const clinT1 = document.getElementById('a12p18-2h-clinical-text-1');
    const clinT2 = document.getElementById('a12p18-2h-clinical-text-2');
    const takeaway = document.getElementById('a12p18-2h-takeaway-text');

    if (badgeText) badgeText.textContent = data.badge;
    if (title) title.textContent = data.title;
    if (subtitle) subtitle.textContent = data.subtitle;
    if (p1) p1.textContent = data.p1;
    if (p2) p2.textContent = data.p2;
    if (p3) p3.textContent = data.p3;

    if (clinTitle) clinTitle.textContent = data.clinTitle;
    if (clinBody) clinBody.textContent = data.clinBody;
    if (clinT1) clinT1.textContent = data.clinT1;
    if (clinT2) clinT2.textContent = data.clinT2;
    if (takeaway) takeaway.textContent = data.takeaway;
  }

  // Event Listeners for Scene Control Buttons
  const btns = root.querySelectorAll('.a12p18-2h-btn');
  btns.forEach(btn => {
    btn.addEventListener('click', function() {
      const targetScene = this.getAttribute('data-scene-target');
      root.setAttribute('data-scene', targetScene);

      btns.forEach(b => b.classList.remove('is-active'));
      this.classList.add('is-active');

      updatePanel(targetScene);
    });

    btn.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        this.click();
      }
    });
  });

  // Event Listeners for Anatomical Hotspots
  const hotspots = root.querySelectorAll('.a12p18-2h-hotspot');
  hotspots.forEach(hs => {
    const target = hs.getAttribute('data-target');

    hs.addEventListener('mouseenter', function() {
      root.setAttribute('data-active-target', target);
      updatePanel(target);
    });

    hs.addEventListener('mouseleave', function() {
      const currentScene = root.getAttribute('data-scene') || 'all';
      root.setAttribute('data-active-target', 'none');
      updatePanel(currentScene);
    });

    hs.addEventListener('click', function() {
      root.setAttribute('data-active-target', target);
      hotspots.forEach(h => h.classList.remove('is-active'));
      this.classList.add('is-active');
      updatePanel(target);
    });

    hs.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        this.click();
      }
    });
  });

})();
